package com.movieworth.api.movie;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.JsonNode;import java.time.LocalDate;import java.util.*;
@Service public class TmdbService {private final MovieRepository repo;private final RestClient client;private final String key;public TmdbService(MovieRepository r,@Value("${movieworth.tmdb.api-key}")String k,@Value("${movieworth.tmdb.base-url}")String base){repo=r;key=k;client=RestClient.builder().baseUrl(base).build();}
public List<Movie> discover(){if(key==null||key.isBlank())throw new IllegalStateException("TMDB_API_KEY is not configured");JsonNode root=client.get().uri("/discover/movie?api_key={key}&sort_by=popularity.desc&region=IN",key).retrieve().body(JsonNode.class);List<Movie> out=new ArrayList<>();if(root!=null&&root.path("results").isArray())for(JsonNode n:root.path("results"))out.add(upsert(n));return out;}
@Transactional public Movie upsert(JsonNode n){long tmdb=n.path("id").asLong();Movie m=repo.findByTmdbId(tmdb).orElseGet(Movie::new);m.setTmdbId(tmdb);m.setTitle(n.path("title").asText("Untitled"));m.setOriginalTitle(n.path("original_title").asText());m.setLanguage(n.path("original_language").asText());String date=n.path("release_date").asText();m.setReleaseDate(date.isBlank()?null:LocalDate.parse(date));m.setPosterPath(n.path("poster_path").asText(null));m.setOverview(n.path("overview").asText());m.setPopularity(n.path("popularity").asDouble());return repo.save(m);}}
